pub fn confLoad(allo: std.mem.Allocator, iozz: std.Io, path: []const u8) !Conf { const byte = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(CF.maxz)) catch |err| { if (err == error.FileNotFound) return .{}; return err; }; return confParse(allo, byte); }
pub fn confKeyz(allo: std.mem.Allocator, byte: []const u8) ?[]const u8 { const valu = std.json.parseFromSliceLeaky(std.json.Value, allo, byte, .{}) catch return null; if (valu != .object) return null; var iter = valu.object.iterator(); while (iter.next()) |item| { var known = false; inline for (@typeInfo(Conf).@"struct".field_names) |fnam| { if (std.mem.eql(u8, fnam, item.key_ptr.*)) known = true; } if (!known) return item.key_ptr.*; } return null; }
pub fn confParse(allo: std.mem.Allocator, byte: []const u8) !Conf { if (confKeyz(allo, byte)) |keyz| { std.debug.print("config error: unknown key \"{s}\" (fix the name or remove it)\n", .{keyz}); return error.BadConfig; } const conf = std.json.parseFromSliceLeaky(Conf, allo, byte, .{ .ignore_unknown_fields = false, .allocate = .alloc_always }) catch return error.BadConfig; try confChek(conf); return conf; }
pub fn confChek(conf: Conf) !void { if ((conf.brow_wind_widt == 0) != (conf.brow_wind_high == 0) or conf.brow_wind_widt > 10000 or conf.brow_wind_high > 10000 or !std.math.isFinite(conf.brow_wind_scal) or (conf.brow_wind_scal != 0 and (conf.brow_wind_scal < 0.25 or conf.brow_wind_scal > 4)) or conf.brow_wind_left < -100 or conf.brow_wind_left > 10000) return error.BadConfig; if (conf.feed_item_maxz == 0 or conf.feed_item_maxz > 500 or conf.feed_text_maxz < 200) return error.BadConfig; for (conf.feed_path_list) |fpth| { if (fpth.len == 0 or fpth[0] != '/') return error.BadConfig; }if (conf.rand_seed_numb != 0) return error.BadConfig; if (conf.type_dely_msec[0] < 30 or conf.type_dely_msec[1] * 2 < conf.type_dely_msec[0] * 3) return error.BadConfig; if (conf.acti_dely_secs[0] < 2 or conf.acti_dely_secs[1] <= conf.acti_dely_secs[0]) return error.BadConfig; if (conf.quie_hour_rang[0] > 23 or conf.quie_hour_rang[1] > 23) return error.BadConfig; if (conf.time_scal_perc < 50 or conf.time_scal_perc > 1000 or conf.mous_step_coun < 8 or conf.mous_step_coun > 200) return error.BadConfig; if (conf.retr_coun_maxz == 0 or conf.retr_coun_maxz > 10 or conf.brow_time_seco == 0) return error.BadConfig; if (!std.mem.eql(u8, conf.lang_main_code, "vi") and !std.mem.eql(u8, conf.lang_main_code, "en")) return error.BadConfig; if (conf.cool_perc_caps == 0 or conf.cool_perc_caps > 100 or conf.wait_maxx_minu == 0) return error.BadConfig; for (conf.noti_chai_orde) |ite| if (!std.mem.eql(u8, ite, "toas") and !std.mem.eql(u8, ite, "file")) return error.BadConfig; for (conf.flow_list) |fl| { if (fl.name.len == 0 or fl.jobs.len == 0) return error.BadConfig; } if (conf.quie_zone_minu < -840 or conf.quie_zone_minu > 840) return error.BadConfig; if (!std.mem.startsWith(u8, conf.base_urlz_main, "http")) return error.BadConfig; for (conf.smar_chai_orde) |ite| if (!std.mem.eql(u8, ite, "clau") and !std.mem.eql(u8, ite, "llam")) return error.BadConfig; if (conf.acct_maxx_coun == 0 or conf.acct_maxx_coun > 20 or conf.acct_gap_secs[0] > conf.acct_gap_secs[1] or conf.aliv_look_hour == 0 or conf.aliv_look_hour > 72) return error.BadConfig; if (conf.map_page_maxx == 0 or conf.map_page_maxx > 200 or conf.map_deep_maxx > 3 or conf.secr_loca_main.len == 0) return error.BadConfig; for (conf.map_seed_list) |ite| if (ite.len == 0 or ite[0] != '/') return error.BadConfig; for (conf.map_allo_list) |ite| if (ite.len == 0 or ite[0] != '/') return error.BadConfig; }
pub fn dataDir(allo: std.mem.Allocator, home: []const u8, conf: Conf) ![]u8 { return pathExpa(allo, home, if (builtin.os.tag == .windows) conf.data_loca_wind else conf.data_loca_unix); }
pub fn feedDir(allo: std.mem.Allocator, home: []const u8, conf: Conf) ![]u8 { return pathExpa(allo, home, if (builtin.os.tag == .windows) conf.feed_dirz_wind else conf.feed_dirz_unix); }
pub fn acctDir(allo: std.mem.Allocator, home: []const u8, conf: Conf, id: []const u8, subz: []const u8) ![]u8 { const root = try dataDir(allo, home, conf); defer allo.free(root); if (subz.len == 0) return std.fs.path.join(allo, &.{ root, "acct", id }); return std.fs.path.join(allo, &.{ root, "acct", id, subz }); }
pub fn subDir(allo: std.mem.Allocator, home: []const u8, conf: Conf, subz: []const u8) ![]u8 { const root = try dataDir(allo, home, conf); defer allo.free(root); return std.fs.path.join(allo, &.{ root, subz }); }
pub fn pathExpa(allo: std.mem.Allocator, home: []const u8, path: []const u8) ![]u8 { if (path.len > 0 and path[0] == CF.tilz) { if (home.len == 0) return error.BadConfig; return std.fmt.allocPrint(allo, "{s}{s}", .{ home, path[1..] }); } return allo.dupe(u8, path); }
